157	inline static uint32_t SixteenAlign(uint32_t a)
158	{
159	    // 16 align down
160	    return a & INVERSE_FIFTEEN;
161	}
162	
163	inline static uint32_t SixteenAlignUp(uint32_t a)
164	{
165	    // 16 aligin up
166	    return (a + FIFTEEN) & INVERSE_FIFTEEN;
167	}
