354	// Update baseN of mm2 according to kernel tiling logic, in order to boost performance
355	void FFNTiling::UpdateMM2BaseNByCoreTiling(uint32_t baseM, uint32_t &mm2BaseN)
356	{
357	    // Step1: determine how many AI cubes are available for each shape
358	    uint32_t aicNum = tilingData.ffnBaseParams.get_coreNum();
359	    uint32_t count = GetSmallElementsNum(tilingData.mm1TilingData.get_baseM());
360	    if (count > 1) {
361	        uint32_t maxExpertParallelism1 = aicNum / Ceil(n1, tilingData.mm1TilingData.get_baseN());
362	        maxExpertParallelism1 = std::min(MAX_EXPERT_PARALLELISM, std::max<uint32_t>(1, maxExpertParallelism1));
363	        uint32_t maxExpertParallelism2 = aicNum / Ceil(n2, mm2BaseN);
364	        maxExpertParallelism2 = std::min(MAX_EXPERT_PARALLELISM, std::max<uint32_t>(1, maxExpertParallelism2));
365	        maxExpertParallelism2 = std::min(count, std::min(maxExpertParallelism2, maxExpertParallelism1));
366	        aicNum = aicNum / std::max<uint32_t>(1, maxExpertParallelism2);
367	    }
368	    // Step2: determine the number of cubes available for N-dim of each shape, and compute the best baseN
369	    if (n2 % SIXTEEN_ALIGN_CONSTANT != 0 && aicNum > 1) {
370	        uint32_t nLoops = aicNum / Ceil(maxTokens, baseM);
371	        uint32_t newmm2BaseN = std::max(minBaseNShape, SixteenAlignUp(n2 / nLoops));
372	        if (nLoops > 1 && newmm2BaseN < mm2BaseN) {
373	            mm2BaseN = newmm2BaseN;
374	        }
375	    }
376	}
