378	ActiveType FFNTiling::GetActiveType(const gert::TilingContext *context, const char *activeType) const
379	{
380	    for (const ActiveMap &item : ACTIVE_MAP) {
381	        size_t len = strlen(item.activeName);
382	        bool isValidActiveType = strlen(activeType) == len;
383	        // use for loop instead of strncasecmp to avoid possible out-of-bounds problems
384	        if (!isValidActiveType) {
385	            continue;
386	        }
387	        for (size_t i = 0; i < len; i++) {
388	            if (tolower(activeType[i]) != item.activeName[i]) {
389	                isValidActiveType = false;
390	                break;
391	            }
392	        }
393	        if (isValidActiveType) {
394	            OP_LOGI(context, "activeType is %s.", activeType);
395	            return item.activeType;
396	        }
397	    }
398	    return ActiveType::INVALID_TYPE;
399	}
