401	ge::graphStatus FFNTiling::GetBs(const gert::TilingContext *context, const gert::StorageShape *xShape)
402	{
403	    int64_t tempBs;
404	    if (is310P) {
405	        tempBs = xShape->GetStorageShape().GetDim(1) * xShape->GetStorageShape().GetDim(DIMS_2);
406	    } else {
407	        tempBs = xShape->GetStorageShape().GetDim(0);
408	        size_t dimNum = xShape->GetStorageShape().GetDimNum() >= 1 ? xShape->GetStorageShape().GetDimNum() - 1 : 0;
409	        for (size_t i = 1; i < dimNum; i++) {
410	            tempBs *= xShape->GetStorageShape().GetDim(i);
411	        }
412	    }
413	    OP_CHECK_IF(xDataTypeSize == 0, OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "get x dtype size is 0"),
414	               return ge::GRAPH_FAILED);
415	    int32_t numInOneBlk = BLOCK_SIZE_FFN / xDataTypeSize;
416	    int32_t maxBs = INT_MAX / numInOneBlk * numInOneBlk;
417	    OP_CHECK_IF(tempBs > maxBs,
418	               OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "32Byte-aligned M dim cannot be greater than INT32_MAX"),
419	               return ge::GRAPH_FAILED);
420	    bs = static_cast<uint64_t>(tempBs);
421	    return ge::GRAPH_SUCCESS;
422	}
