424	void FFNTiling::UpdateMaxTokens()
425	{
426	    // When expert tokens are unknown,
427	    // maxTokens is set as 'bs', which is the maximum possible number of tokens for a single expert,
428	    // maxTokensCheckOpt is set as the mean value of number of tokens
429	    maxTokens = bs;
430	    maxTokensCheckOpt = expertNum <= 1 ? bs : (bs + expertNum - 1) / expertNum;
431	}
432	
433	void FFNTiling::CheckMSD()
434	{
435	    uint64_t bestMaxTokenMsd =
436	        static_cast<uint64_t>(static_cast<float>(n1) / static_cast<float>(TYPICAL1_N1) * TINY_TOKEN_BOUND);
437	    bool isMsdN1K1 =
438	        (n1 % BEST_BASEN_MSD == 0) && n1 > MSD_N_THRESHOLD && (k1 % BEST_BASEN_MSD == 0) && k1 > MSD_K_THRESHOLD;
439	    isMsdCase = isMsdN1K1 && (xDataType == ge::DT_BF16 || xDataType == ge::DT_FLOAT16) && weight1Dtype == ge::DT_INT8 &&
440	                maxTokensCheckOpt <= bestMaxTokenMsd && bs <= 512; // 512: max M value in msd-scenario
441	}
