443	ge::graphStatus FFNTiling::TilingCalcAndSetting(const gert::TilingContext *context,
444	                                                const matmul_tiling::PlatformInfo &platInfo,
445	                                                matmul_tiling::DataType matmulDtype)
446	{
447	    if (is310P) {
448	        OP_CHECK_IF(CalMM1TilingBaseMNKBasicBlock(context, platInfo) != ge::GRAPH_SUCCESS,
449	                   OP_LOGW(context, "Calculate mm1 baseMNK failed!"), return ge::GRAPH_FAILED);
450	        OP_CHECK_IF(CalMM2TilingBaseMNKBasicBlock(context, platInfo) != ge::GRAPH_SUCCESS,
451	                   OP_LOGW(context, "Calculate mm2 baseMNK failed!"), return ge::GRAPH_FAILED);
452	    } else {
453	        OP_CHECK_IF(CalMM1TilingBaseMNK(context, platInfo) != ge::GRAPH_SUCCESS,
454	                   OP_LOGW(context, "Calculate mm1 baseMNK failed!"), return ge::GRAPH_FAILED);
455	        OP_CHECK_IF(CalMM2TilingBaseMNK(platInfo) != ge::GRAPH_SUCCESS,
456	                   OP_LOGW(context, "Calculate mm2 baseMNK failed!"), return ge::GRAPH_FAILED);
457	    }
458	
459	    OP_CHECK_IF(FFNSetMM1Tiling(context, platInfo, matmulDtype) != ge::GRAPH_SUCCESS,
460	               OP_LOGW(context, "Set mm1 tiling failed!"), return ge::GRAPH_FAILED);
461	    OP_CHECK_IF(FFNSetMM2Tiling(context, platInfo, matmulDtype) != ge::GRAPH_SUCCESS,
462	               OP_LOGW(context, "Set mm2 tiling failed!"), return ge::GRAPH_FAILED);
463	
464	    OP_LOGI(context, "Calc tiling success!");
465	    isTilingDataValid = true;
466	    return ge::GRAPH_SUCCESS;
467	}
