469	ge::graphStatus FFNTiling::FFNGetScaleGroupNum(const gert::TilingContext *context, const gert::Tensor *tokensArrTensor)
470	{
471	    uint32_t scale1GroupNum = 1;
472	    uint32_t scale2GroupNum = 1;
473	    isPerGroup = false;
474	    if (context->GetOptionalInputTensor(ANTIQUANT_SCALE1_INDEX)) {
475	        const gert::StorageShape *antiScale1Shape = context->GetOptionalInputShape(ANTIQUANT_SCALE1_INDEX);
476	        uint32_t antiScale1DimNum = antiScale1Shape->GetStorageShape().GetDimNum();
477	        const gert::StorageShape *antiScale2Shape = context->GetOptionalInputShape(ANTIQUANT_SCALE2_INDEX);
478	        if (tokensArrTensor == nullptr && antiScale1DimNum == DIMS_2) { // scale shape is (G,N)
479	            scale1GroupNum = antiScale1Shape->GetStorageShape().GetDim(0);
480	            scale2GroupNum = antiScale2Shape->GetStorageShape().GetDim(0);
481	            isPerGroup = true;
482	        } else if (tokensArrTensor != nullptr && antiScale1DimNum == DIMS_3) { // scale shape is (E,G,N)
483	            scale1GroupNum = antiScale1Shape->GetStorageShape().GetDim(1);
484	            scale2GroupNum = antiScale2Shape->GetStorageShape().GetDim(1);
485	            isPerGroup = true;
486	        }
487	    }
488	    tilingData.ffnBaseParams.set_scale1GroupNum(scale1GroupNum);
489	    tilingData.ffnBaseParams.set_scale2GroupNum(scale2GroupNum);
490	    return ge::GRAPH_SUCCESS;
491	}
