527	ge::graphStatus FFNTiling::GetInputShape(const gert::TilingContext *context)
528	{
529	    const gert::StorageShape *xShape = context->GetInputShape(X_INDEX);
530	    OP_CHECK_IF(xShape == nullptr, OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "xShape is nullptr"), return ge::GRAPH_FAILED);
531	    const gert::StorageShape *weight1Shape = context->GetInputShape(WEIGHT1_INDEX);
532	    OP_CHECK_IF(weight1Shape == nullptr, OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "weight1Shape is nullptr"),
533	               return ge::GRAPH_FAILED);
534	    const gert::StorageShape *weight2Shape = context->GetInputShape(WEIGHT2_INDEX);
535	    OP_CHECK_IF(weight2Shape == nullptr, OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "weight2Shape is nullptr"),
536	               return ge::GRAPH_FAILED);
537	
538	    bool isTokensIndex = GetTokensIndexFlag(context);
539	    uint32_t tokensIndexFlag = static_cast<uint32_t>(isTokensIndex);
540	    tilingData.ffnBaseParams.set_tokensIndexFlag(tokensIndexFlag);
541	
542	    // high-dimension input fuses m-axis
543	    OP_CHECK_IF(GetBs(context, xShape) != ge::GRAPH_SUCCESS,
544	               OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "Get M dim value failed"), return ge::GRAPH_FAILED);
545	    k1 = xShape->GetStorageShape().GetDim(xShape->GetStorageShape().GetDimNum() - 1);
546	    auto tokensArrTensor = context->GetOptionalInputTensor(TOKENS_ARR_INDEX);
547	    if (tokensArrTensor) {
548	        // origin MOEFFN
549	        n1 = weight1Shape->GetStorageShape().GetDim(2); // 2: the index of N in weight(E, K, N)
550	        n2 = weight2Shape->GetStorageShape().GetDim(2); // 2: the index of N in weight(E, K, N)
551	        expertNum = weight1Shape->GetStorageShape().GetDim(0);
552	        int64_t tokenNum = tokensArrTensor->GetShapeSize();
553	        OP_CHECK_IF(
554	            expertNum != tokenNum || tokenNum > MAX_EXPERT_NUM || expertNum == 0,
555	            OPS_REPORT_VECTOR_INNER_ERR(
556	                context->GetNodeName(),
557	                "Invalid input expert_tokens. ExpertNum in expert_tokens %ld not equal to expertNum %u in weight, "
558	                "or expertNum %u is larger than max value: %u or equal to 0",
559	                tokenNum, expertNum, expertNum, MAX_EXPERT_NUM),
560	            return ge::GRAPH_FAILED);
561	    } else { // origin FFN
562	        if (is310P) {
563	            k1 = xShape->GetStorageShape().GetDim(0) * xShape->GetStorageShape().GetDim(DIMS_3);
564	            n1 = weight1Shape->GetStorageShape().GetDim(0) * weight1Shape->GetStorageShape().GetDim(DIMS_3);
565	            n2 = weight2Shape->GetStorageShape().GetDim(0) * weight2Shape->GetStorageShape().GetDim(DIMS_3);
566	        } else {
567	            n1 = weight1Shape->GetStorageShape().GetDim(1);
568	            n2 = weight2Shape->GetStorageShape().GetDim(1);
569	        }
570	        expertNum = 1;
571	    }
572	    return ge::GRAPH_SUCCESS;
573	}
