588	ge::graphStatus FFNTiling::CheckAndGetBasicInfo(gert::TilingContext *context, const FFNCompileInfo *compileInfoPtr)
589	{
590	    const uint32_t coreNum = compileInfoPtr->coreNum;
591	    is310P = compileInfoPtr->socVersion == platform_ascendc::SocVersion::ASCEND310P;
592	
593	    OP_CHECK_IF(
594	        (coreNum == 0 || compileInfoPtr->ubSize == 0 || compileInfoPtr->l1Size == 0 || compileInfoPtr->l0CSize == 0 ||
595	         compileInfoPtr->l0ASize == 0 || compileInfoPtr->l0BSize == 0),
596	        OPS_REPORT_VECTOR_INNER_ERR(
597	            context->GetNodeName(),
598	            "platform info is invalid, coreNum=%u, ubSize=%lu, l1Size=%lu, l0CSize=%lu, l0ASize=%lu, l0BSize=%lu",
599	            coreNum, compileInfoPtr->ubSize, compileInfoPtr->l1Size, compileInfoPtr->l0CSize, compileInfoPtr->l0ASize,
600	            compileInfoPtr->l0BSize),
601	        return ge::GRAPH_FAILED);
602	    OP_CHECK_IF(FFNParamsCheck(context) != ge::GRAPH_SUCCESS, OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "params is invalid"),
603	               return ge::GRAPH_FAILED);
