612	ge::graphStatus FFNTiling::TilingWithDifferentKN(gert::TilingContext *context, const FFNCompileInfo *compileInfoPtr,
613	                                                 const uint32_t aicNum)
614	{
615	    matmul_tiling::PlatformInfo mmPlatInfo = MmGetPlatInfo(compileInfoPtr);
616	    ge::graphStatus tilingStatus = ge::GRAPH_FAILED;
617	
618	    // n1 can be divided to 20 cores at least, BEST_BASEN for each, and the second matrix cannot load to L1 fully
619	    // In this scenario, tiling might be computed in performance branch
620	    bool whetherN1K1Satisfy = k1 > BEST_L1_PART2 / ((BEST_BASEN / CONSTANT_TWO) * xDataTypeSize) &&
621	                              n1 > BEST_BASEN * aicNum / (CONSTANT_TWO * CONSTANT_TWO);
622	    // cases in 310P will  also be in performance branch
623	    if ((n1 != 0 && k1 == n2 && n1 == SixteenAlign(n1) && whetherN1K1Satisfy) || is310P) {
624	        tilingStatus = TilingCalcAndSetting(context, mmPlatInfo, static_cast<matmul_tiling::DataType>(xDataType));
625	    }
626	
627	    if (tilingStatus != ge::GRAPH_SUCCESS) {
628	        FFNSingleCoreTiling(context, ubSize_);
629	        if (n1 != 0) {
630	            OP_CHECK_IF(FFNApiTiling(context, mmPlatInfo, static_cast<matmul_tiling::DataType>(xDataType)) !=
631	                           ge::GRAPH_SUCCESS,
632	                       OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "run matmul tiling faild"), return ge::GRAPH_FAILED);
633	        }
634	    }
635	    return ge::GRAPH_SUCCESS;
636	}
