652	ge::graphStatus FFNTiling::RunFusionKernelTiling(gert::TilingContext *context)
653	{
654	    Init();
655	    const FFNCompileInfo *compileInfoPtr = reinterpret_cast<const FFNCompileInfo *>(context->GetCompileInfo());
656	    OP_CHECK_IF(compileInfoPtr == nullptr, OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "compileInfoPtr is null"),
657	               return ge::GRAPH_FAILED);
658	
659	    const uint32_t aicNum = compileInfoPtr->aicCoreNum;
660	    const uint32_t aivNum = compileInfoPtr->aivCoreNum;
661	
662	    OP_CHECK_IF(CheckAndGetBasicInfo(context, compileInfoPtr) != ge::GRAPH_SUCCESS,
663	               OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "run CheckAndGetBasicInfo faild"), return ge::GRAPH_FAILED);
664	    UpdateMaxTokens();
665	    CheckMSD();
666	
667	    if (bs == 0 || k1 == 0 || n2 == 0) {
668	        context->SetTilingKey(0);
669	        context->SetBlockDim(0);
670	        tilingData.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
671	        context->GetRawTilingData()->SetDataSize(tilingData.GetDataSize());
672	        return ge::GRAPH_SUCCESS;
673	    }
674	
675	    SetTilingBaseParams(context, compileInfoPtr, aicNum);
676	
677	    if (n1 != 0 && tilingData.ffnBaseParams.get_activeType() >= static_cast<uint32_t>(ActiveType::GEGLU)) {
678	        OP_CHECK_IF(FFNGlu(context, compileInfoPtr->ubSize, compileInfoPtr->l1Size, compileInfoPtr->l0CSize, aivNum) !=
679	                       ge::GRAPH_SUCCESS,
680	                   OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "run FFNGlu faild"), return ge::GRAPH_FAILED);
681	        PrintFFNTiling(context, true);
682	        return ge::GRAPH_SUCCESS;
683	    }
684	    auto tokensArrTensor = context->GetOptionalInputTensor(TOKENS_ARR_INDEX);
685	    FFNGetQuantScale(context, tokensArrTensor); // get quant isSmooth info
686	
687	    OP_CHECK_IF(TilingWithDifferentKN(context, compileInfoPtr, aicNum) != ge::GRAPH_SUCCESS,
688	               OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "run TilingWithDifferentKN faild"), return ge::GRAPH_FAILED);
689	
690	    tilingData.ffnBaseParams.set_maxTokens(maxTokens);
691	    tilingData.mm1TilingData.set_usedCoreNum(aicNum);
692	    tilingData.mm2TilingData.set_usedCoreNum(aicNum);
693	
694	    FFNGetScaleGroupNum(context, tokensArrTensor);
695	    OP_CHECK_IF(FFNSetTilingData(context) != ge::GRAPH_SUCCESS,
696	               OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "FFNSetTilingData failed"), return ge::GRAPH_FAILED);
697	    OP_LOGI(context, "RunFusionKernelTiling end");
698	    return ge::GRAPH_SUCCESS;
699	}
