761	/*
762	 * @brief FFN params check.
763	 * @param context gert::TilingContext
764	 * The op struct need to adapt is shown as follows:
765	 * 1) has experts
766	 *    x(M,K1)  weight1(E,K1,N1)  bias1(E,N1)
767	 *          \           /            /
768	 *             MM1(M,N1)
769	 *                 |
770	 *            active_layer  weight1(E,K2,N2)  bias2(E,N2)
771	 *                 |          /                /
772	 *           MM2(M,N2), N2=K1
773	 *
774	 * 2) no experts
775	 *    x(M,K1)  weight1(K1,N1)  bias1(N1)
776	 *          \           /            /
777	 *             MM1(M,N1)
778	 *                 |
779	 *            active_layer  weight1(K2,N2)  bias2(N2)
780	 *                 |          /                /
781	 *           MM2(M,N2), N2=K1
782	 *  Notice: E/bias may or may not be. The output shape is equal to x's.
783	 * @return ge::STATUS.
784	 */
785	ge::graphStatus FFNTiling::FFNParamsCheck(gert::TilingContext *context)
786	{
787	    const gert::RuntimeAttrs *attrs = context->GetAttrs();
788	    OP_CHECK_NULL_WITH_CONTEXT(context, attrs);
789	    const char *activeType = attrs->GetAttrPointer<char>(FFN_ATTR_INDEX_ACTIVATION);
790	    OP_CHECK_NULL_WITH_CONTEXT(context, activeType);
791	    ActiveType activationType = GetActiveType(context, activeType);
792	    OP_CHECK_IF(activationType == ActiveType::INVALID_TYPE,
793	               OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "activeType does not match any of the preset types"),
794	               return ge::GRAPH_FAILED);
795	    tilingData.ffnBaseParams.set_activeType(static_cast<uint32_t>(activationType));
796	
797	    OP_CHECK_IF(DataTypeCheck(context) != ge::GRAPH_SUCCESS || FormatCheck(context) != ge::GRAPH_SUCCESS,
798	               OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "the data type and format is invalid."), return ge::GRAPH_FAILED);
799	    weightDataTypeSize = GetSizeByDataType(weight1Dtype);
800	    innerPrecise = HIGH_PRECISION;
801	    const int64_t *innerPrecisePtr = attrs->GetAttrPointer<int64_t>(FFN_ATTR_INDEX_INNER_PRECISE);
802	    if (innerPrecisePtr != nullptr) {
803	        innerPrecise = static_cast<int32_t>(*innerPrecisePtr);
804	    }
805	    OP_LOGI(context, "Inner_precise is %d.", innerPrecise);
806	
807	    OP_CHECK_IF(innerPrecise != HIGH_PRECISION && innerPrecise != HIGH_PERFORMANCE,
808	               OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "Invalid innerPrecise. Attr inner_precise only support 0/1."),
809	               return ge::GRAPH_FAILED);
810	
811	    OP_CHECK_IF(innerPrecise != HIGH_PERFORMANCE && activationType == ActiveType::GEGLU,
812	               OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "Invalid innerPrecise. GEGLU only support high preformance."),
813	               return ge::GRAPH_FAILED);
814	    return ge::GRAPH_SUCCESS;
815	}
816	
817	ge::graphStatus FFNTiling::FFNSetUbDivideBlk()
818	{
819	    ubBlockAlign = UB_PER_BLOCK_ALIGN;
820	    if (xDataType == ge::DT_FLOAT16 && (weight1Dtype == ge::DT_INT8 || weight1Dtype == ge::DT_INT4)) {
821	        ubDivideBlkNum = UB_ANTIQUANT_BLOCK_NUM_FP16;
822	        ubIoBlkNum = UB_ANTIQUANT_IO_USED_BLOCK_FP16;
823	        ubBlockAlign = UB_ANTIQUANT_PER_BLOCK_ALIGN_FP16;
824	        return ge::GRAPH_SUCCESS;
825	    } else if (xDataType == ge::DT_BF16 && (weight1Dtype == ge::DT_INT8 || weight1Dtype == ge::DT_INT4)) {
826	        ubDivideBlkNum = UB_ANTIQUANT_BLOCK_NUM_BP16;
827	        ubIoBlkNum = UB_ANTIQUANT_IO_USED_BLOCK_BP16;
828	        return ge::GRAPH_SUCCESS;
829	    } else if ((xDataType == ge::DT_FLOAT16 || xDataType == ge::DT_BF16) && innerPrecise == HIGH_PRECISION) {
830	        ubDivideBlkNum = UB_PRECISION_BLOCK_NUM_FP16;
831	        ubIoBlkNum = UB_PRECISION_IO_USED_BLOCK_FP16;
832	        return ge::GRAPH_SUCCESS;
833	    } else if (xDataType == ge::DT_FLOAT16 && weight1Dtype == ge::DT_FLOAT16) {
834	        ubDivideBlkNum = UB_PEFORMENCE_BLOCK_NUM_FP16;
835	        ubIoBlkNum = UB_PEFORMENCE_IO_USED_BLOCK_FP16;
836	        if (is310P) {
837	            ubBlockAlign = UB_PER_BLOCK_ALIGN_310P;
838	        }
839	        return ge::GRAPH_SUCCESS;
840	    } else if (xDataType == ge::DT_INT8) {
841	        if (outputDtype == ge::DT_BF16) {
842	            isQuantBf16 = true;
843	            ubDivideBlkNum = UB_QUANT_BLOCK_NUM_BF16_OUT;
844	            ubIoBlkNum = UB_QUANT_IO_BLOCK_NUM_BF16_OUT;
845	            return ge::GRAPH_SUCCESS;
846	        } else if (outputDtype == ge::DT_FLOAT16) {
847	            ubDivideBlkNum = UB_QUANT_BLOCK_NUM_FP16_OUT;
848	            ubIoBlkNum = UB_QUANT_IO_BLOCK_NUM_FP16_OUT;
849	            return ge::GRAPH_SUCCESS;
850	        } else {
851	            return ge::GRAPH_FAILED;
852	        }
853	    }
854	    return ge::GRAPH_FAILED;
855	}
856	
857	ge::graphStatus FFNTiling::FFNCalUbSize(uint32_t baseN, uint32_t divideBlkNum, uint32_t ioBlkNum, uint32_t &baseM)
858	{
859	    if (divideBlkNum == 0 || baseN == 0 || ubBlockAlign == 0) {
860	        return ge::GRAPH_FAILED;
861	    }
862	    ubCalSize = ubSize_ / divideBlkNum;
863	    ubCalSize = ubCalSize / ubBlockAlign * ubBlockAlign; // 16k/8k/4k align
864	    ubRestBytes = ubSize_ - ubCalSize * ioBlkNum;
865	    ubRestBytes = ubRestBytes / UB_BLOCK_UNIT_SIZE * UB_BLOCK_UNIT_SIZE; // 32B align
866	    if (ubCalSize == 0 || ubRestBytes == 0) {
867	        return ge::GRAPH_FAILED;
868	    }
869	    baseM = ubCalSize / baseN;   // activate function baseM
870	    baseM = SixteenAlign(baseM);
871	    tilingData.ffnSingleCoreParams.set_ubCalSize(ubCalSize);
872	    if (isMsdCase) {
873	        tilingData.ffnSingleCoreParams.set_ubRestBytes(ubSize_ + ((expertNum * sizeof(int64_t) + ALIGN32) & ~ALIGN32));
874	    } else {
875	        tilingData.ffnSingleCoreParams.set_ubRestBytes(ubRestBytes);
876	    }
877	    return ge::GRAPH_SUCCESS;
878	}
