880	ge::graphStatus FFNTiling::CalMM1ValidUbBytes(int64_t &mm1VaildUbBytes) const
881	{
882	    if (innerPrecise == HIGH_PRECISION) {
883	        mm1VaildUbBytes = ubSize_ / UB_DIVIDE_NUM_HIGH_PRECISION;
884	    }
885	    if (xDataType == ge::DT_INT8) {
886	        if (outputDtype == ge::DT_BF16) {
887	            mm1VaildUbBytes = ubSize_ / UB_DIVIDE_NUM_QUANT_BF16;
888	        } else if (deqscaleDtype == ge::DT_FLOAT) {
889	            mm1VaildUbBytes = ubSize_ / UB_DIVIDE_NUM_QUANT_DEQ_FLOAT32;
890	        } else {
891	            mm1VaildUbBytes = ubSize_ / UB_DIVIDE_NUM_QUANT;
892	        }
893	    }
894	    return ge::GRAPH_SUCCESS;
895	}
