897	ge::graphStatus FFNTiling::CalMM1BaseM(const gert::TilingContext *context, const uint32_t baseN, const uint64_t l0CSize,
898	                                       const int64_t mm1VaildUbBytes, uint32_t &baseM)
899	{
900	    if (baseN == 0) {
901	        return ge::GRAPH_FAILED;
902	    }
903	    OP_CHECK_IF(FFNCalUbSize(baseN, ubDivideBlkNum, ubIoBlkNum, baseM) != ge::GRAPH_SUCCESS,
904	               OP_LOGW(context, "calculate ub failed."), return ge::GRAPH_FAILED);
905	
906	    uint32_t maxBaseM = std::min<uint32_t>(SixteenAlign(maxTokens), MAX_BASEM);
907	    baseM = std::min<uint32_t>(mm1VaildUbBytes / baseN, baseM);
908	
909	    // calculate cube baseM by l0c size
910	    baseM = std::min<uint32_t>(l0CSize / (baseN * FP32_DATATYPE_SIZE), baseM);
911	    baseM = std::min<uint32_t>(maxBaseM, baseM);
912	    baseM = SixteenAlign(baseM); // align down
913	    if (baseM == 0) {
914	        return ge::GRAPH_FAILED;
915	    }
916	    return ge::GRAPH_SUCCESS;
917	}
