919	ge::graphStatus FFNTiling::CalMM1TilingBaseMNBasicBlock(const gert::TilingContext *context, const uint64_t l0CSize,
920	                                                        const int64_t mm1VaildUbBytes, uint64_t basicBlkOperTimes,
921	                                                        uint32_t &baseN)
922	{
923	    uint32_t coreNum = tilingData.ffnBaseParams.get_coreNum();
924	    uint32_t nCal = n1 - 1;
925	    uint32_t mCal = maxTokens - 1;
926	    uint32_t baseM = MATMUL_MIN_SHAPE;
927	    float lastRatio = 0.f;
928	    for (uint32_t tmpBaseN = baseN; tmpBaseN >= SMALL_TOKEN_BOUND; tmpBaseN -= TINY_TOKEN_BOUND) {
929	        OP_CHECK_IF(CalMM1BaseM(context, tmpBaseN, l0CSize, mm1VaildUbBytes, baseM) != ge::GRAPH_SUCCESS,
930	                   OP_LOGW(context, "calculate mm1 baseM failed."), return ge::GRAPH_FAILED);
931	        uint32_t blockDimN = Ceil(n1, tmpBaseN);
932	        uint64_t curBasicBlkOperTimes = Ceil(Ceil(maxTokens, baseM) * blockDimN, coreNum) * coreNum;
933	        if (curBasicBlkOperTimes < basicBlkOperTimes) {
934	            basicBlkOperTimes = curBasicBlkOperTimes;
935	            lastRatio = 0.0;
936	            baseM1_ = baseM;
937	            baseN = tmpBaseN;
938	        }
939	        float nRatio = nCal % tmpBaseN * 1.0f / tmpBaseN;
940	        for (uint32_t tmpBaseM = baseM; tmpBaseM >= SMALL_TOKEN_BOUND; tmpBaseM -= TINY_TOKEN_BOUND) {
941	            uint64_t blockDim = Ceil(maxTokens, tmpBaseM) * blockDimN;
942	            if (blockDim > basicBlkOperTimes) {
943	                break;
944	            }
945	            float curRatio = mCal % tmpBaseM * nRatio / tmpBaseM;
946	            if (blockDim == basicBlkOperTimes && curRatio > lastRatio) {
947	                lastRatio = curRatio;
948	                baseM1_ = tmpBaseM;
949	                baseN = tmpBaseN;
950	            }
951	        }
952	    }
953	    return ge::GRAPH_SUCCESS;
954	}
955	
956	ge::graphStatus FFNTiling::CalMMTilingBaseMNBasicBlock(const uint64_t basicBlkOperTimes, const uint32_t n,
957	                                                       uint32_t &baseM, uint32_t &baseN) const
958	{
959	    bool isRecomputed = false; // variable indicates whether baseM/baseN is recomputed
960	    uint32_t blockDimM = Ceil(maxTokens, baseM);
961	    uint32_t blockDimN = Ceil(n, baseN);
962	    uint64_t blockDim = blockDimM * blockDimN;
963	    if (blockDimM == 1) {
964	        baseN = Ceil(n, basicBlkOperTimes);
965	        baseN = SixteenAlignUp(baseN);
966	        isRecomputed = true;
967	    } else if (blockDimN == 1) {
968	        baseM = Ceil(maxTokens, basicBlkOperTimes);
969	        baseM = SixteenAlignUp(baseM);
970	        isRecomputed = true;
971	    }
972	    blockDim = Ceil(maxTokens, baseM) * Ceil(n, baseN);
973	    if (blockDim >= basicBlkOperTimes && isRecomputed) {
974	        return ge::GRAPH_SUCCESS;
975	    }
976	
977	    uint32_t initialBaseN = baseN;
978	    uint32_t nCal = n - 1;
979	    uint32_t mCal = maxTokens - 1;
980	    float lastRatio = 0.f;
981	    for (uint32_t tmpBaseM = baseM; tmpBaseM >= TINY_TOKEN_BOUND; tmpBaseM -= TINY_TOKEN_BOUND) {
982	        float mRatio = mCal % tmpBaseM * 1.0f / tmpBaseM;
983	        blockDimM = Ceil(maxTokens, tmpBaseM);
984	        for (uint32_t tmpBaseN = initialBaseN; tmpBaseN >= TINY_TOKEN_BOUND; tmpBaseN -= TINY_TOKEN_BOUND) {
985	            blockDim = blockDimM * Ceil(n, tmpBaseN);
986	            if (blockDim > basicBlkOperTimes) {
987	                break;
988	            }
989	            float curRatio = nCal % tmpBaseN * mRatio / tmpBaseN;
990	            if (blockDim == basicBlkOperTimes && curRatio > lastRatio) {
991	                lastRatio = curRatio;
992	                baseM = tmpBaseM;
993	                baseN = tmpBaseN;
994	            }
995	        }
996	    }
997	    return ge::GRAPH_SUCCESS;
998	}
