1000	ge::graphStatus FFNTiling::CalMM1TilingBaseMNKBasicBlock(const gert::TilingContext *context,
1001	                                                         const matmul_tiling::PlatformInfo &platInfo)
1002	{
1003	    int64_t mm1VaildUbBytes = ubSize_ / (UB_DIVIDE_NUM * xDataTypeSize);
1004	    uint32_t coreNum = tilingData.ffnBaseParams.get_coreNum();
1005	    uint32_t baseN = std::min<uint32_t>(SixteenAlign(n1), BEST_BASEN);
1006	
1007	    OP_CHECK_IF(FFNSetUbDivideBlk() != ge::GRAPH_SUCCESS,
1008	               OP_LOGW(context, "set ub device block failed."), return ge::GRAPH_FAILED);
1009	    OP_CHECK_IF(CalMM1BaseM(context, baseN, platInfo.l0CSize, mm1VaildUbBytes, baseM1_) != ge::GRAPH_SUCCESS,
1010	               OP_LOGW(context, "calculate mm1 baseM failed."), return ge::GRAPH_FAILED);
1011	    uint32_t blockDimM = Ceil(maxTokens, baseM1_);
1012	    uint64_t blockDim = blockDimM * Ceil(n1, baseN);
1013	    uint64_t basicBlkOperTimes = Ceil(blockDim, coreNum) * coreNum;
1014	    if (blockDim > coreNum) {
1015	        if (blockDimM == 1) {
1016	            baseN = Ceil(n1, basicBlkOperTimes);
1017	            baseN = SixteenAlignUp(baseN);
1018	        } else if (baseN < baseM1_) {
1019	            baseM1_ = Ceil(maxTokens, basicBlkOperTimes);
1020	            baseM1_ = SixteenAlignUp(baseM1_);
1021	        } else {
1022	            OP_CHECK_IF(CalMM1TilingBaseMNBasicBlock(context, platInfo.l0CSize, mm1VaildUbBytes, basicBlkOperTimes,
1023	                                                    baseN) != ge::GRAPH_SUCCESS,
1024	                       OP_LOGW(context, "mm1 calculate baseMN failed."), return ge::GRAPH_FAILED);
1025	        }
1026	    } else {
1027	        OP_CHECK_IF(CalMMTilingBaseMNBasicBlock(basicBlkOperTimes, n1, baseM1_, baseN) != ge::GRAPH_SUCCESS,
1028	                   OP_LOGW(context, "mm1 calculate baseMN failed."), return ge::GRAPH_FAILED);
1029	    }
1030	
1031	    // calculate baseK in considering l0B double buffer, so divide 2
1032	    baseK1_ = (platInfo.l0BSize / CONSTANT_TWO) / (baseN * xDataTypeSize);
1033	    baseK1_ = std::min<uint32_t>((platInfo.l0ASize / CONSTANT_TWO) / (baseM1_ * xDataTypeSize), baseK1_);
1034	    baseK1_ = SixteenAlign(baseK1_);
1035	    if (baseK1_ == 0) {
1036	        return ge::GRAPH_FAILED;
1037	    }
1038	
1039	    mm1VaildUbBytes = baseM1_ * baseN;
1040	    tilingData.ffnSingleCoreParams.set_baseM1(baseM1_);
1041	    tilingData.ffnSingleCoreParams.set_baseN1(baseN);
1042	    tilingData.ffnSingleCoreParams.set_mm1ResUbSize(mm1VaildUbBytes);
1043	    return ge::GRAPH_SUCCESS;
1044	}
1045	
1046	ge::graphStatus FFNTiling::CalMM1TilingBaseMNK(const gert::TilingContext *context,
1047	                                               const matmul_tiling::PlatformInfo &platInfo)
1048	{
1049	    int64_t mm1VaildUbBytes = ubSize_ / UB_DIVIDE_NUM;
1050	    CalMM1ValidUbBytes(mm1VaildUbBytes);
1051	    uint32_t baseN = MATMUL_MIN_SHAPE;
1052	    if (isMsdCase) {
1053	        baseN = BEST_BASEN_MSD;
1054	        xDataTypeSize = 1;
1055	    } else {
1056	        baseN = BEST_BASEN;
1057	    }
1058	    // calculate baseK in considering l0B double buffer, so divide 2
1059	    baseK1_ = (platInfo.l0BSize / CONSTANT_TWO) / (baseN * xDataTypeSize);
1060	    baseK1_ = SixteenAlign(baseK1_); // align down
1061	    if (baseK1_ == 0) {
1062	        return ge::GRAPH_FAILED;
1063	    }
1064	
1065	    uint32_t maxBaseM = platInfo.l0CSize / (baseN * FP32_DATATYPE_SIZE);
1066	    // calculate baseM in considering l0A double buffer, so divide 2
1067	    baseM1_ = std::min<uint32_t>((platInfo.l0ASize / CONSTANT_TWO) / (baseK1_ * xDataTypeSize), maxBaseM);
1068	    if (maxTokens <= TINY_TOKEN_BOUND) {
1069	        baseM1_ = TINY_TOKEN_BOUND;
1070	    } else if (maxTokens <= SMALL_TOKEN_BOUND) {
1071	        baseM1_ = SMALL_TOKEN_BOUND;
1072	    }
1073	    baseM1_ = SixteenAlign(baseM1_);
1074	    if (baseM1_ == 0) {
1075	        return ge::GRAPH_FAILED;
1076	    }
1077	    // calculate vector baseM by ub size
1078	    uint32_t baseM = mm1VaildUbBytes / (baseN * xDataTypeSize);
1079	    if (FFNSetUbDivideBlk() == ge::GRAPH_SUCCESS) {
1080	        OP_CHECK_IF(FFNCalUbSize(baseN, ubDivideBlkNum, ubIoBlkNum, baseM) != ge::GRAPH_SUCCESS,
1081	                   OP_LOGW(context, "calculate ub failed."), return ge::GRAPH_FAILED);
1082	    }
1083	    baseM = SixteenAlign(baseM);
1084	    if (baseM == 0) {
1085	        return ge::GRAPH_FAILED;
1086	    }
1087	    // baseM in cube can be divided by baseM in ub
1088	    uint32_t cubeMFactor = baseM1_ / SIXTEEN_ALIGN_CONSTANT;
1089	    uint32_t vectorMFactor = baseM / SIXTEEN_ALIGN_CONSTANT;
1090	    for (uint32_t i = vectorMFactor; i >= 1; --i) {
1091	        if (cubeMFactor % i == 0) {
1092	            baseM = i * SIXTEEN_ALIGN_CONSTANT;
1093	            break;
1094	        }
1095	    }
1096	    mm1VaildUbBytes = baseN * baseM; // numbers in UB, not bytes
1097	    tilingData.ffnSingleCoreParams.set_baseM1(baseM);
1098	    tilingData.ffnSingleCoreParams.set_baseN1(baseN);
1099	    tilingData.ffnSingleCoreParams.set_mm1ResUbSize(mm1VaildUbBytes);
1100	    return ge::GRAPH_SUCCESS;
1101	}
