1177	void FFNTiling::FFNCalMMStep(const uint32_t baseM, const uint32_t baseN, const uint32_t baseK,
1178	                             TCubeTiling &mmTilingData)
1179	{
1180	    // whether enable double buffer in L1B
1181	    bool divTwo = (maxTokens <= SMALL_TOKEN_BOUND && expertNum > 1);
1182	    uint32_t bestL1Part1 = BEST_L1_PART1;
1183	    uint32_t bestL1Part2 = BEST_L1_PART2;
1184	
1185	    if (is310P) {
1186	        divTwo = 1;
1187	        bestL1Part1 = BEST_L1_PART_310P;
1188	        bestL1Part2 = BEST_L1_PART_310P;
1189	    }
1190	    uint32_t mmStepM = 1;
1191	    uint32_t mmStepN = 1;
1192	    uint32_t mmStepKa = (bestL1Part1 >> 1) / (baseM * baseK * xDataTypeSize);
1193	    uint32_t mmStepKb = (bestL1Part2 >> static_cast<uint32_t>(divTwo)) / (baseN * baseK * xDataTypeSize);
1194	    if (mmStepKa > mmStepKb) {
1195	        mmStepKa = mmStepKa / mmStepKb * mmStepKb;
1196	    } else if (mmStepKa < mmStepKb) {
1197	        mmStepKb = mmStepKb / mmStepKa * mmStepKa;
1198	    }
1199	    if (xDataType == ge::DT_INT8 && maxTokensCheckOpt > SMALL_TOKEN_BOUND) {
1200	        mmStepKb = mmStepKb / CONSTANT_TWO;
1201	    }
1202	    uint32_t mmDepthA1 = mmStepKa << 1;
1203	    uint32_t mmDepthB1 = mmStepKb << 1;
1204	    if (xDataType == ge::DT_INT8 && (!isSmooth) && outputDtype == ge::DT_FLOAT16 && deqscaleDtype == ge::DT_UINT64 &&
1205	        maxTokens <= SMALL_TOKEN_BOUND && expertNum > 1 && tilingData.ffnBaseParams.get_n1() % BEST_BASEN == 0 &&
1206	        tilingData.ffnBaseParams.get_n2() % BEST_BASEN == 0) {
1207	        mmStepKb = mmStepKb / CONSTANT_TWO;
1208	        mmStepN = CONSTANT_TWO;
1209	        mmTilingData.set_iterateOrder(1);
1210	    }
1211	
1212	    mmTilingData.set_stepKa(mmStepKa);
1213	    mmTilingData.set_depthA1(mmDepthA1);
1214	    mmTilingData.set_stepKb(mmStepKb);
1215	    mmTilingData.set_depthB1(mmDepthB1);
1216	    mmTilingData.set_stepN(mmStepN);
1217	    mmTilingData.set_stepM(mmStepM);
1218	
1219	    // xDataTypeSize is modified in msd-branch, so get the right value again
1220	    xDataTypeSize = GetSizeByDataType(xDataType);
1221	}
