1223	ge::graphStatus FFNTiling::FFNSetMM1Tiling(const gert::TilingContext *context,
1224	                                           const matmul_tiling::PlatformInfo &platInfo,
1225	                                           matmul_tiling::DataType matmulDtype)
1226	{
1227	    matmul_tiling::MatmulApiTiling mm1(platInfo);
1228	    uint32_t baseN1 = tilingData.ffnSingleCoreParams.get_baseN1();
1229	
1230	    mm1.SetBType(matmul_tiling::TPosition::GM, wFormat, matmulDtype, false);
1231	    if (is310P) {
1232	        mm1.SetAType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::NZ, matmulDtype, false);
1233	        mm1.SetCType(matmul_tiling::TPosition::VECCALC, matmul_tiling::CubeFormat::NZ,
1234	                     matmul_tiling::DataType::DT_FLOAT16);
1235	    } else {
1236	        mm1.SetAType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmulDtype, false);
1237	        mm1.SetCType(matmul_tiling::TPosition::VECCALC, matmul_tiling::CubeFormat::ND_ALIGN,
1238	                     matmul_tiling::DataType::DT_FLOAT16);
1239	    }
1240	    SetBiasInfo(context, mm1, BIAS1_INDEX);
1241	
1242	    mm1.SetOrgShape(maxTokens, tilingData.ffnBaseParams.get_n1(), tilingData.ffnBaseParams.get_k1());
1243	    mm1.SetShape(maxTokens, baseN1, tilingData.ffnBaseParams.get_k1());
1244	    if (!isMsdCase) {
1245	        mm1.SetFixSplit(std::min(baseM1_, maxTokens), baseN1);
1246	    }
1247	    mm1.SetBufferSpace(platInfo.l1Size, platInfo.l0CSize, tilingData.ffnSingleCoreParams.get_mm1ResUbSize());
1248	    if (mm1.GetTiling(tilingData.mm1TilingData) == -1) {
1249	        return ge::GRAPH_FAILED;
1250	    }
1251	    tilingData.mm1TilingData.set_shareMode(0);
1252	    tilingData.mm1TilingData.set_shareL1Size(platInfo.l1Size);
1253	    tilingData.mm1TilingData.set_shareL0CSize(platInfo.l0CSize);
1254	    tilingData.mm1TilingData.set_dbL0C(1); // disable l0c double buffer
1255	    tilingData.mm1TilingData.set_baseM(baseM1_);
1256	    tilingData.mm1TilingData.set_baseN(baseN1);
1257	    tilingData.mm1TilingData.set_baseK(baseK1_);
1258	    FFNCalMMStep(baseM1_, baseN1, baseK1_, tilingData.mm1TilingData);
1259	
1260	    return ge::GRAPH_SUCCESS;
1261	}
