1263	ge::graphStatus FFNTiling::FFNSetMM2Tiling(const gert::TilingContext *context,
1264	                                           const matmul_tiling::PlatformInfo &platInfo,
1265	                                           matmul_tiling::DataType matmulDtype)
1266	{
1267	    matmul_tiling::MatmulApiTiling mm2(platInfo);
1268	    uint32_t baseM2 = mm2BaseM;
1269	    uint32_t baseN2 = tilingData.ffnSingleCoreParams.get_baseN2();
1270	    mm2.SetAType(matmul_tiling::TPosition::GM, xFormat, matmulDtype, false);
1271	    mm2.SetBType(matmul_tiling::TPosition::GM, wFormat, matmulDtype, false);
1272	    mm2.SetCType(matmul_tiling::TPosition::GM, yFormat, matmul_tiling::DataType::DT_FLOAT16);
1273	    SetBiasInfo(context, mm2, BIAS2_INDEX);
1274	
1275	    mm2.SetOrgShape(maxTokens, tilingData.ffnBaseParams.get_n2(), tilingData.ffnBaseParams.get_n1());
1276	    mm2.SetShape(maxTokens, baseN2, tilingData.ffnBaseParams.get_n1());
1277	    if (!isMsdCase) {
1278	        mm2.SetFixSplit(std::min(baseM2, maxTokens), baseN2);
1279	    }
1280	    mm2.SetBufferSpace(platInfo.l1Size, platInfo.l0CSize);
