1285	    tilingData.mm2TilingData.set_shareL1Size(platInfo.l1Size);
1286	    tilingData.mm2TilingData.set_shareL0CSize(platInfo.l0CSize);
1287	    tilingData.mm2TilingData.set_dbL0C(1); // disable l0c double buffer
1288	    tilingData.mm2TilingData.set_baseM(baseM2);
1289	    tilingData.mm2TilingData.set_baseN(baseN2);
1290	    tilingData.mm2TilingData.set_baseK(baseK2_);
1291	    FFNCalMMStep(baseM2, baseN2, baseK2_, tilingData.mm2TilingData);
1292	
1293	    return ge::GRAPH_SUCCESS;
1294	}
