1296	ge::graphStatus FFNTiling::FFNGlu(gert::TilingContext *context, uint64_t ubSize, uint64_t l1Size, uint64_t l0CSize,
1297	                                  uint32_t aivNum)
1298	{
1299	    OP_CHECK_IF(FFNGluParamsCheck(context) != ge::GRAPH_SUCCESS,
1300	               OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "FFN Glu param is invaild"), return ge::GRAPH_FAILED);
1301	
1302	    FFNGluCalMM1Tiling(ubSize, l0CSize);
1303	    OP_CHECK_IF(FFNGluSetMM1Tiling(context, l1Size, l0CSize, static_cast<matmul_tiling::DataType>(xDataType), aivNum) !=
1304	                   ge::GRAPH_SUCCESS,
1305	               OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "FFN Glu set mm1 tiling faild"), return ge::GRAPH_FAILED);
1306	    FFNGluCalMM2Tiling(l0CSize);
1307	    OP_CHECK_IF(FFNGluSetMM2Tiling(context, l1Size, l0CSize, static_cast<matmul_tiling::DataType>(xDataType)) !=
1308	                   ge::GRAPH_SUCCESS,
1309	               OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "FFN Glu set mm2 tiling faild"), return ge::GRAPH_FAILED);
1310	
1311	    context->SetTilingKey(2); // 2: for glu template
1312	    size_t *workspaces = context->GetWorkspaceSizes(1);
1313	    auto workspace1Size = baseM1_ * baseN1_ * xDataTypeSize * 4 * aivNum; // 4: pingpong buffer and left/right part
1314	    auto workspace2Size = maxTokens * n1 / 2 * xDataTypeSize; // 2: dim in n1 should be divided by 2
1315	    tilingData.ffnBaseParams.set_workspace1Size(workspace1Size);
1316	    tilingData.ffnBaseParams.set_workspace2Size(workspace2Size);
1317	    workspaces[0] = workspace1Size + workspace2Size + SYS_WORKSPACE_SIZE;
1318	    // Check tiling data size not greater than capacity
1319	    OP_CHECK_IF(tilingData.GetDataSize() > context->GetRawTilingData()->GetCapacity(),
1320	               OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "actual tiling data size %zu > context tiling data size %zu",
1321	                                           tilingData.GetDataSize(), context->GetRawTilingData()->GetCapacity()),
1322	               return ge::GRAPH_FAILED);
1323	    tilingData.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
1324	    context->GetRawTilingData()->SetDataSize(tilingData.GetDataSize());
1325	    return ge::GRAPH_SUCCESS;
1326	}
