1328	ge::graphStatus FFNTiling::FFNGluParamsCheck(const gert::TilingContext *context) const
1329	{
1330	    // n1 should be a even number
1331	    OP_CHECK_IF((n1 % 2 != 0),
1332	               OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "the glu activation function only supports n1 is even"),
1333	               return ge::GRAPH_FAILED);
1334	
1335	    OP_CHECK_IF((xDataType != ge::DT_FLOAT16),
1336	               OPS_REPORT_VECTOR_INNER_ERR(
1337	                   context->GetNodeName(), "the glu activation function only supports the data type is float16, the dtype is %s",
1338	                   TypeUtils::DataTypeToSerialString(xDataType).c_str()),
1339	               return ge::GRAPH_FAILED);
1340	    // only supported in no-expert scenario
1341	    bool hasExperts = context->GetOptionalInputTensor(TOKENS_ARR_INDEX) != nullptr;
1342	    OP_CHECK_IF(
1343	        hasExperts,
1344	        OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "the glu activation function only supports the scene without experts"),
1345	        return ge::GRAPH_FAILED);
1346	    // k2 should be equal to n1/2
1347	    const gert::StorageShape *weight2Shape = context->GetInputShape(WEIGHT2_INDEX);
1348	    size_t kIndex = hasExperts ? 1 : 0;
1349	    auto k2 = weight2Shape->GetStorageShape().GetDim(kIndex);
1350	    OP_CHECK_IF((n1 / 2 != k2),
1351	               OPS_REPORT_VECTOR_INNER_ERR(
1352	                   context->GetNodeName(), "the glu activation function only supports k2(%ld) is equal to n1(%u) / 2", k2, n1),
1353	               return ge::GRAPH_FAILED);
1354	    return ge::GRAPH_SUCCESS;
1355	}
