1357	ge::graphStatus FFNTiling::SetMMTilingType(const gert::TilingContext *context, bool isMM1,
1358	                                           matmul_tiling::DataType matmulDtype,
1359	                                           matmul_tiling::MatmulApiTiling &mm) const
1360	{
1361	    mm.SetAType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmulDtype, false);
1362	    mm.SetBType(matmul_tiling::TPosition::GM, wFormat, matmulDtype, false);
1363	    uint32_t biasIndex;
1364	    if (isMM1) {
1365	        mm.SetCType(matmul_tiling::TPosition::VECCALC, matmul_tiling::CubeFormat::ND,
1366	                    matmul_tiling::DataType::DT_FLOAT16);
1367	        biasIndex = BIAS1_INDEX;
1368	    } else {
1369	        mm.SetCType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16);
