1382	
1383	ge::graphStatus FFNTiling::FFNGluCalMM1Tiling(uint64_t ubSize, uint64_t l0CSize)
1384	{
1385	    int64_t mm1VaildUbBytes = ubSize / GLU_UB_DIVIDE_NUM_FP16;
1386	    uint32_t tempN1 = n1 / 2; // 2: n1 dim should divide 2
1387	
1388	    uint32_t baseN = BEST_BASEN;
1389	    uint32_t baseM;
1390	    while (tempN1 < baseN) {
1391	        baseN = baseN >> 1;
1392	    }
1393	    if (baseN < MATMUL_MIN_SHAPE) {
1394	        baseN = MATMUL_MIN_SHAPE;
1395	    }
1396	    // calculate vector baseM by ub size
1397	    uint32_t maxBaseM = mm1VaildUbBytes / (baseN * xDataTypeSize);
1398	    baseM = std::min(MAX_UB_BLOCK / baseN, maxBaseM);
1399	    while (maxTokens < baseM) {
1400	        baseM = baseM >> 1;
1401	    }
1402	    if (baseM < MATMUL_MIN_SHAPE) {
1403	        baseM = MATMUL_MIN_SHAPE;
1404	    }
1405	
1406	    // cube basic block size should be a multiple of vector basic block
1407	    uint32_t aicAIVFactor = 4;
1408	    if (baseM * aicAIVFactor <= maxTokens) {
1409	        baseM1_ = baseM * aicAIVFactor;
1410	        baseN1_ = baseN;
1411	        // basic block size cannot exceed l0c size
1412	        maxBaseM = l0CSize / (baseN1_ * FP32_DATATYPE_SIZE);
1413	        if (baseN1_ == BEST_BASEN && maxBaseM < maxTokens) {
1414	            baseM1_ = maxBaseM;
1415	        }
1416	    } else {
1417	        baseM1_ = baseM;
1418	        baseN1_ = baseN;
1419	    }
1420	
1421	    mm1VaildUbBytes = baseM * baseN;
1422	    tilingData.ffnSingleCoreParams.set_baseM1(baseM);
1423	    tilingData.ffnSingleCoreParams.set_baseN1(baseN);
1424	    tilingData.ffnSingleCoreParams.set_mm1ResUbSize(mm1VaildUbBytes);
1425	    return ge::GRAPH_SUCCESS;
1426	}
1427	
1428	ge::graphStatus FFNTiling::FFNGluSetMM1Tiling(gert::TilingContext *context, uint64_t l1Size, uint64_t l0CSize,
1429	                                              matmul_tiling::DataType matmulDtype, uint32_t aivNum)
1430	{
1431	    matmul_tiling::MatmulApiTiling mm1;
1432	    SetMMTilingType(context, true, matmulDtype, mm1);
1433	
1434	    uint32_t tilingCoreNum = aivNum;
1435	    uint32_t tempN1 = n1 / 2; // 2: n1 dim should divide 2
1436	
1437	    uint32_t n1Loops = (tempN1 + baseN1_ - 1) / baseN1_;
1438	    if (n1Loops > tilingCoreNum) {
1439	        n1Loops = tilingCoreNum;
1440	    }
1441	    uint32_t singleCoreN1 = (tempN1 + n1Loops - 1) / n1Loops;
1442	    singleCoreN1 = (singleCoreN1 + FIFTEEN) & ~FIFTEEN;
1443	    singleCoreN1 = singleCoreN1 > baseN1_ ? singleCoreN1 : baseN1_;
1444	    n1Loops = (tempN1 + singleCoreN1 - 1) / singleCoreN1;
1445	
1446	    uint32_t m1Loops = tilingCoreNum / n1Loops;
1447	    uint32_t singleCoreM1 = (maxTokens + m1Loops - 1) / m1Loops;
1448	    singleCoreM1 = (singleCoreM1 + FIFTEEN) & ~FIFTEEN;
1449	    while (baseM1_ > MATMUL_MIN_SHAPE && baseM1_ > singleCoreM1) {
1450	        baseM1_ = baseM1_ >> 1;
1451	    }
1452	
1453	    mm1.SetOrgShape(maxTokens, tilingData.ffnBaseParams.get_n1(), tilingData.ffnBaseParams.get_k1());
1454	    mm1.SetShape(singleCoreM1, singleCoreN1, tilingData.ffnBaseParams.get_k1());
1455	    mm1.SetFixSplit(baseM1_, baseN1_);
1456	    mm1.SetBufferSpace(l1Size, l0CSize, tilingData.ffnSingleCoreParams.get_mm1ResUbSize());
1457	
1458	    if (mm1.GetTiling(tilingData.mm1TilingData) == -1) {
1459	        return ge::GRAPH_FAILED;
1460	    }
1461	    tilingData.mm1TilingData.set_shareMode(0);
1462	    tilingData.mm1TilingData.set_shareL1Size(l1Size);
1463	    tilingData.mm1TilingData.set_shareL0CSize(l0CSize);
1464	    return ge::GRAPH_SUCCESS;
1465	}
1466	
1467	ge::graphStatus FFNTiling::FFNGluCalMM2Tiling(uint64_t l0CSize)
1468	{
1469	    baseN2_ = GLU_BASEN;
1470	    while (n2 < baseN2_) {
1471	        baseN2_ = baseN2_ >> 1;
1472	    }
1473	    if (baseN2_ < MATMUL_MIN_SHAPE) {
1474	        baseN2_ = MATMUL_MIN_SHAPE;
1475	    }
1476	
1477	    uint32_t maxBaseM = l0CSize / (baseN2_ * FP32_DATATYPE_SIZE);
1478	    baseM2_ = MAX_BASE_BLOCK / baseN2_;
1479	    while (baseM2_ > maxBaseM || maxTokens < baseM2_) {
1480	        baseM2_ = baseM2_ >> 1;
1481	    }
1482	    if (baseM2_ < MATMUL_MIN_SHAPE) {
1483	        baseM2_ = MATMUL_MIN_SHAPE;
1484	    }
1485	
1486	    uint32_t tilingCoreNum = tilingData.ffnBaseParams.get_coreNum(); // number of cubes in mm2
1487	
1488	    uint32_t n2Loops = (n2 + baseN2_ - 1) / baseN2_;
1489	    if (n2Loops > tilingCoreNum) {
1490	        n2Loops = tilingCoreNum;
1491	    }
1492	    singleN2 = (n2 + n2Loops - 1) / n2Loops;
1493	    singleN2 = (singleN2 + FIFTEEN) & ~FIFTEEN;
1494	    singleN2 = singleN2 > baseN2_ ? singleN2 : baseN2_;
1495	    n2Loops = (n2 + singleN2 - 1) / singleN2;
1496	
1497	    uint32_t m2Loops = tilingCoreNum / n2Loops;
1498	    singleM2 = (maxTokens + m2Loops - 1) / m2Loops;
1499	    singleM2 = (singleM2 + FIFTEEN) & ~FIFTEEN;
1500	    while (baseM2_ > MATMUL_MIN_SHAPE && baseM2_ > singleM2) {
1501	        baseM2_ = baseM2_ >> 1;
1502	    }
1503	    tilingData.ffnSingleCoreParams.set_baseN2(baseN2_);
1504	
1505	    return ge::GRAPH_SUCCESS;
1506	}
