1508	ge::graphStatus FFNTiling::FFNGluSetMM2Tiling(gert::TilingContext *context, uint64_t l1Size, uint64_t l0CSize,
1509	                                              matmul_tiling::DataType matmulDtype)
1510	{
1511	    matmul_tiling::MatmulApiTiling mm2;
1512	    SetMMTilingType(context, false, matmulDtype, mm2);
1513	    auto k2 = tilingData.ffnBaseParams.get_n1() / 2; // k2 = n1 / 2
1514	    mm2.SetOrgShape(maxTokens, tilingData.ffnBaseParams.get_n2(), k2);
1515	    mm2.SetShape(singleM2, singleN2, k2);
1516	    mm2.SetFixSplit(baseM2_, baseN2_);
1517	    mm2.SetBufferSpace(l1Size, l0CSize);
1518	    if (mm2.GetTiling(tilingData.mm2TilingData) == -1) {
1519	        return ge::GRAPH_FAILED;
1520	    }
1521	    tilingData.mm2TilingData.set_shareMode(0);
1522	    tilingData.mm2TilingData.set_shareL1Size(l1Size);
1523	    tilingData.mm2TilingData.set_shareL0CSize(l0CSize);
1524	
1525	    return ge::GRAPH_SUCCESS;
1526	}
