1528	ge::graphStatus FFNTiling::DataTypeCheck(gert::TilingContext *context)
1529	{
1530	    auto x = context->GetInputDesc(X_INDEX);
1531	    auto weight1 = context->GetInputDesc(WEIGHT1_INDEX);
1532	    auto weight2 = context->GetInputDesc(WEIGHT2_INDEX);
1533	    auto output = context->GetOutputDesc(0);
1534	    const gert::Tensor *weight2Tensor = context->GetInputTensor(WEIGHT2_INDEX);
1535	    OP_CHECK_NULL_WITH_CONTEXT(context, weight2Tensor);
1536	    OP_CHECK_NULL_WITH_CONTEXT(context, x);
1537	    OP_CHECK_NULL_WITH_CONTEXT(context, weight1);
1538	    OP_CHECK_NULL_WITH_CONTEXT(context, weight2);
1539	    OP_CHECK_NULL_WITH_CONTEXT(context, output);
1540	    xDataType = x->GetDataType();
1541	    weight1Dtype = weight1->GetDataType();
1542	    auto weight2Dtype = weight2->GetDataType();
1543	    outputDtype = output->GetDataType();
1544	    OP_CHECK_IF((weight1Dtype != weight2Dtype ||
1545	                (xDataType != weight1Dtype && weight1Dtype != ge::DT_INT8 && weight1Dtype != ge::DT_INT4)),
1546	               OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "weight1 and weight2 data type are not same."),
1547	               return ge::GRAPH_FAILED);
1548	    OP_CHECK_IF((xDataType != ge::DT_FLOAT16 && xDataType != ge::DT_INT8 && xDataType != ge::DT_BF16),
1549	               OPS_REPORT_VECTOR_INNER_ERR(
1550	                   context->GetNodeName(), "x, weight1 and weight2 data type only support float16/int8/bfloat16/int4, the dtype is %s",
1551	                   TypeUtils::DataTypeToSerialString(xDataType).c_str()),
1552	               return ge::GRAPH_FAILED);
1553	    xDataTypeSize = GetSizeByDataType(xDataType);
1554	    OP_CHECK_IF((outputDtype != ge::DT_FLOAT16 && outputDtype != ge::DT_BF16),
1555	               OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "output data type only support float16/bfloat16, the dtype is %s",
1556	                                           TypeUtils::DataTypeToSerialString(outputDtype).c_str()),
1557	               return ge::GRAPH_FAILED);
1558	
1559	    minBaseNShape = MATMUL_MIN_SHAPE;
1560	    if (xDataType == ge::DT_INT8) {
1561	        minBaseNShape = MATMUL_MIN_SHAPE_INT8;
1562	        if (context->GetOptionalInputTensor(DEQSCALE1_INDEX)) {
1563	            auto deqscale1 = context->GetOptionalInputDesc(DEQSCALE1_INDEX);
1564	            deqscaleDtype = deqscale1->GetDataType();
1565	        }
1566	    }
1567	    return ge::GRAPH_SUCCESS;
1568	}
