1570	ge::graphStatus FFNTiling::FormatCheck(const gert::TilingContext *context)
1571	{
1572	    auto x = context->GetInputDesc(X_INDEX);
1573	    auto weight1 = context->GetInputDesc(WEIGHT1_INDEX);
1574	    auto weight2 = context->GetInputDesc(WEIGHT2_INDEX);
1575	    auto output = context->GetOutputDesc(0);
1576	    ge::Format inputFormat = static_cast<ge::Format>(ge::GetPrimaryFormat(x->GetStorageFormat()));
1577	    ge::Format weight1Format = static_cast<ge::Format>(ge::GetPrimaryFormat(weight1->GetStorageFormat()));
1578	    ge::Format weight2Format = static_cast<ge::Format>(ge::GetPrimaryFormat(weight2->GetStorageFormat()));
1579	    ge::Format outputFormat = static_cast<ge::Format>(ge::GetPrimaryFormat(output->GetStorageFormat()));
1580	    OP_CHECK_IF(
1581	        (weight1Format != weight2Format || inputFormat != outputFormat),
1582	        OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "InputFormat, weight1Format, weight2Format and outputFormat are not same"),
1583	        return ge::GRAPH_FAILED);
1584	    if (is310P) {
1585	        OP_CHECK_IF(inputFormat != ge::FORMAT_FRACTAL_NZ,
1586	                   OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(),
1587	                                               "inputFormat and outputFormat only support NZ, the format is %s",
1588	                                               TypeUtils::FormatToSerialString(inputFormat).c_str()),
1589	                   return ge::GRAPH_FAILED);
1590	    } else {
1591	        OP_CHECK_IF(IsPrivateFormat(inputFormat),
1592	                   OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "Current inputFormat is %s, which is not supported",
1593	                                               TypeUtils::FormatToSerialString(inputFormat).c_str()),
1594	                   return ge::GRAPH_FAILED);
1595	    }
1596	    wFormat = weight1Format == ge::FORMAT_FRACTAL_NZ ? matmul_tiling::CubeFormat::NZ : matmul_tiling::CubeFormat::ND;
1597	    xFormat = inputFormat == ge::FORMAT_FRACTAL_NZ ? matmul_tiling::CubeFormat::NZ : matmul_tiling::CubeFormat::ND;
1598	    yFormat = outputFormat == ge::FORMAT_FRACTAL_NZ ? matmul_tiling::CubeFormat::NZ : matmul_tiling::CubeFormat::ND;
1599	    return ge::GRAPH_SUCCESS;
1600	}
