1602	inline ge::graphStatus FFNTiling::N1EqualZeroWithBias2(uint64_t ubSize)
1603	{
1604	    int64_t mm1VaildUbBytes = ubSize / UB_DIVIDE_NUM_N1_ZERO;
1605	    uint32_t baseN = mm1VaildUbBytes / 2;
1606	    if (n2 < baseN) {
1607	        baseN = n2;
1608	    }
1609	
1610	    baseN = (baseN + SIXTEEN_ALIGN_CONSTANT - 1) / SIXTEEN_ALIGN_CONSTANT * SIXTEEN_ALIGN_CONSTANT;
1611	    tilingData.ffnSingleCoreParams.set_baseN2(baseN);
1612	    tilingData.ffnSingleCoreParams.set_ubCalSize(baseN);
1613	    tilingData.ffnSingleCoreParams.set_ubRestBytes(0);
1614	    return ge::GRAPH_SUCCESS;

