1789	void FFNTiling::CalMM2Single(uint32_t baseM2, uint32_t baseN2)
1790	{
1791	    uint32_t align = std::max(BLOCK_SIZE_FFN / xDataTypeSize, baseN2) - 1;
1792	    singleM2 = (maxTokens + CALC_MM2_SINGLE_CORE_NUM - 1) / CALC_MM2_SINGLE_CORE_NUM;
1793	    if (singleM2 < baseM2) {
1794	        singleM2 = baseM2;
1795	    }
1796	    if (singleM2 > maxTokens) {
1797	        singleM2 = maxTokens;
1798	    }
1799	    singleM2 = (singleM2 + FIFTEEN) & ~FIFTEEN;
1800	    uint32_t m2Loops = (maxTokens + singleM2 - 1) / singleM2;
1801	    uint32_t n2Loops = 1;
1802	    singleN2 = n2;
1803	    AdjustMM2MNLoops(align, m2Loops, n2Loops);
1804	    if (m2Loops != 0) {
1805	        singleM2 = (maxTokens + m2Loops - 1) / m2Loops;
1806	    }
1807	    auto singleM2Tmp = singleM2;
1808	    singleM2 = (singleM2 + FIFTEEN) & ~FIFTEEN;
1809	    if (singleM2 * m2Loops >= singleM2Tmp * (m2Loops + 1)) {
1810	        singleM2 = singleM2Tmp;
1811	    }
1812	    if (n2Loops != 0) {
1813	        singleN2 = (n2 + n2Loops - 1) / n2Loops;
1814	    }
1815	    singleN2 = (singleN2 + align) & ~align;
1816	    if (singleM2 > maxTokens) {
1817	        singleM2 = maxTokens;
1818	    }
1819	    return;
1820	}
1821	
1822	void FFNTiling::AdjustMM2MNLoops(const uint32_t align, uint32_t &m2Loops, uint32_t &n2Loops)
1823	{
1824	    if (m2Loops < CALC_MM2_SINGLE_CORE_NUM) {
1825	        uint32_t maxMLoops = 0;
1826	        uint32_t maxNLoops = 0;
1827	        uint32_t maxUsedCore = 0;
1828	        if (m2Loops > CALC_MM2_SINGLE_CORE_NUM / CONSTANT_TWO) {
1829	            singleM2 *= CONSTANT_TWO;
1830	        }
1831	        while (singleM2 > 0) {
1832	            m2Loops = (maxTokens + singleM2 - 1) / singleM2;
1833	            if (m2Loops == 0) {
1834	                break;
1835	            }
1836	            n2Loops = CALC_MM2_SINGLE_CORE_NUM / m2Loops;
1837	            if (n2Loops == 0) {
1838	                break;
1839	            }
1840	            singleN2 = (n2 + n2Loops - 1) / n2Loops;
1841	            singleN2 = (singleN2 + align) & ~align;
1842	            n2Loops = (n2 + singleN2 - 1) / singleN2;
1843	            if (m2Loops * n2Loops > maxUsedCore) {
1844	                maxUsedCore = m2Loops * n2Loops;
1845	                maxMLoops = m2Loops;
1846	                maxNLoops = n2Loops;
1847	            }
1848	            if (maxUsedCore == CALC_MM2_SINGLE_CORE_NUM) {
1849	                break;
1850	            }
1851	            if (singleM2 > SIXTEEN_ALIGN_CONSTANT) {
1852	                singleM2 -= SIXTEEN_ALIGN_CONSTANT;
1853	            } else {
1854	                break;
1855	            }
1856	        }
1857	        m2Loops = maxMLoops;
1858	        n2Loops = maxNLoops;
1859	        if (maxUsedCore < CALC_MM2_SINGLE_CORE_NUM) {
1860	            singleM2 = (maxTokens + CALC_MM2_SINGLE_CORE_NUM - 1) / CALC_MM2_SINGLE_CORE_NUM;
1861	            if (maxTokens > (CALC_MM2_SINGLE_CORE_NUM - 1) * singleM2) {
1862	                m2Loops = CALC_MM2_SINGLE_CORE_NUM;
1863	                n2Loops = 1;
1864	            }
1865	        }
1866	    }
1867	}
