88	ge::graphStatus SAFFNTilingComp::SAFFNTilingMM() {
89	    m = MATMUL_SIZE;
90	    batchSize = bm / MATMUL_SIZE;
91	    dataNumPerBatchD = m * n;
92	    dataNumPerBatchA = m * k;
93	    bmmFormerNum = batchSize % aivNum;
94	    bmmTailNum = aivNum - bmmFormerNum;
95	    bmmTailBatchNum = batchSize / aivNum;
96	    bmmFormerBatchNum = bmmTailBatchNum + 1;
